window.addEventListener("scroll",(function(){const e=document.getElementById("mainNav");window.scrollY>50?e.classList.add("scrolled"):e.classList.remove("scrolled")})),document.querySelectorAll('a[href^="#"]').forEach((e=>{e.addEventListener("click",(function(e){const t=this.getAttribute("href");if(!t||"#"===t)return;const o=document.querySelector(t);o&&(e.preventDefault(),o.scrollIntoView({behavior:"smooth"}))}))}));